head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gBzTyp = '';
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        scwin.hideDebugCtrls();
        scwin.resizeToWin();
        scwin.getParam();
        scwin.init();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30007.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    edt_FromDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 365)); // 1년전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    // fn_list_sync();

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Discls_OnLoadCompleted
 * @description dts_Discls 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Discls_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30007.dts_Discls_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Discls_OnDblClick
 * @description grd_Discls 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Discls_OnDblClick = async function(row, colid) {
    try {
        await scwin.setAcpt_No(grd_Discls, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30007.grd_Discls_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30007.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30007.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    try {
        popUpCalendar2(edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30007.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_FromDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30007.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30007.btn_Search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let url = '';
    // alert('[gBzTyp]'+gBzTyp);
    if (scwin.gBzTyp === 'A') {
        url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LIST_DSCL_FOR_REG" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.dsclmgt.select.report.term" + "&{P}param01=" + txb_ISUR_CD.getValue() + "&{P}param02=" + edt_FromDate.getValue() + "&{P}param03=" + edt_ToDate.getValue() + // 종료일자
            "&SCREN_ID=" + 'ULDSTF30007.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    } else {
        url += "&SEARCH_TYP=Y";
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&STRT_DD=" + edt_FromDate.getValue();
        url += "&END_DD=" + edt_ToDate.getValue();
        url += "&SCREN_ID=" + 'ULDSTF30007.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }
    const sbmOptions = {
        id : "sbm_dts_Discls",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Discls=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function() {
    const vTemp = frame.FrameID;
    const Temp2 = vTemp.split("|")[1];
    const Temp3 = vTemp.split("|")[2];
    if (Temp3 !== undefined) {
        scwin.gBzTyp = Temp3.split("=")[1];
    }
    const vISUR_CD = Temp2.split("=")[1];
    txb_ISUR_CD.setValue(vISUR_CD);
};

/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 480;
    frame.Height = 530;
};

/**
 * @method
 * @name hideDebugCtrls
 * @description 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    panel_debug.hide();
};

/**
 * @method
 * @name setAcpt_No
 * @description set Acpt No 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {String} ColID ColID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAcpt_No = async function(GridID, row, ColID) {
    const arrPar = new Array();
    let rtn = undefined;
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    if (scwin.fn_SetPar === "fn_setDiscls") {
        // 온라인통보에서 공시시각을 셋팅한다.
        // alert(fn_SetPar);
        arrPar[0] = objDataID.getCellData(row, "ACPT_NO");
        arrPar[1] = objDataID.getCellData(row, "DISCLS_TITLE");
        arrPar[2] = objDataID.getCellData(row, "DISCLS_PUBL_DDTM");
        rtn = scwin.fn_SetPar(arrPar);
    } else if (scwin.fn_SetPar !== undefined) {
        arrPar[0] = objDataID.getCellData(row, "ACPT_NO");
        arrPar[1] = objDataID.getCellData(row, "DISCLS_TITLE");
        arrPar[2] = objDataID.getCellData(row, "DISCLS_PUBL_DDTM");
        rtn = scwin.fn_SetPar(arrPar);
    }
    if ((rtn === undefined) || (rtn)) {
        await $c.win.closePopup();
    }
};
